const watchlist = [];

for (const item of $input.all()) {
  const row = item.json;

  const symbol = String(row.symbol || '').trim().toUpperCase();
  const enabledValue = row.enabled;

  const enabled =
    enabledValue === true ||
    String(enabledValue).toLowerCase() === 'true' ||
    String(enabledValue).toLowerCase() === 'yes' ||
    String(enabledValue) === '1';

  // Skip disabled rows or rows without a symbol
  if (!enabled || !symbol) {
    continue;
  }

  watchlist.push({
    symbol,
    company_name: row.company_name || symbol,
    sector: row.sector || '',
    notes: row.notes || ''
  });
}

if (!watchlist.length) {
  throw new Error('No enabled symbols were found in the Google Sheets watchlist.');
}

// Create symbols array from the watchlist
const symbols = watchlist.map(item => item.symbol);

// Return a single item containing both
return [
  {
    json: {
      watchlist,
      symbols
    }
  }
];

const response = $json;
const calendar = Array.isArray(response.data) ? response.data : [];

// Get watchlist from the previous watchlist preparation node
const watchlistData = $('Prepare Watchlist Context').first().json;
const watchlist = Array.isArray(watchlistData.watchlist)
  ? watchlistData.watchlist
  : [];

// Create a quick lookup for enabled watchlist symbols
const enabledSymbols = new Set(
  watchlist.map(item =>
    String(item.symbol || '').trim().toUpperCase()
  )
);

// Create today's start date
const start = new Date();
start.setHours(0, 0, 0, 0);

// Create end date = 7 days from today
const end = new Date(start);
end.setDate(end.getDate() + 7);

// Filter dividend calendar
const filtered = calendar.filter(item => {
  const symbol = String(item.symbol || '')
    .trim()
    .toUpperCase();

  const date = new Date(item.ex_dividend_date);

  return (
    enabledSymbols.has(symbol) &&
    !Number.isNaN(date.getTime()) &&
    date >= start &&
    date <= end
  );
});

// Add watchlist information to each dividend candidate
const dividendCandidates = filtered.map(item => {
  const symbol = String(item.symbol || '')
    .trim()
    .toUpperCase();

  const watch = watchlist.find(
    w => String(w.symbol || '').trim().toUpperCase() === symbol
  );

  return {
    ...item,
    symbol,
    company_name: watch?.company_name || item.company_name || symbol,
    sector: watch?.sector || '',
    watchlist_notes: watch?.notes || ''
  };
});

// If no candidates found, return empty output
if (!dividendCandidates.length) {
  return [];
}

// Return one consolidated item
return [
  {
    json: {
      dividend_candidates: dividendCandidates,
      symbols: dividendCandidates.map(item => item.symbol)
    }
  }
];

const response = $json;
const fundamentals = Array.isArray(response.data) ? response.data : [];

return [{
  json: {
    fundamentals
  }
}];

const candidates = $('Prepare Fundamentals Request').first().json.dividend_candidates || [];
const fundamentals = $json.fundamentals || [];

const fundamentalsMap = new Map(
  fundamentals.map(item => [String(item.symbol || '').toUpperCase(), item])
);

return candidates.map(candidate => {
  const symbol = String(candidate.symbol || '').toUpperCase();
  const fundamental = fundamentalsMap.get(symbol);

  return {
    json: {
      ...candidate,
      ...(fundamental || {}),
      symbol
    }
  };
}).filter(item => item.json.share_price !== undefined);

return $input.all().map(item => {
  const data = item.json;

  const text = data.output?.[0]?.content?.find(
    content => content.type === 'output_text'
  )?.text || '';

  let parsed = {};

  try {
    parsed = JSON.parse(text);
  } catch (error) {
    parsed = {
      caution_note: 'Potential dividend sustainability risk detected.',
      key_concern: 'Review payout ratio, earnings trend and dividend history.',
      investor_question: 'Is the current dividend yield supported by sustainable earnings?'
    };
  }

  return {
    json: {
      ...data,
      caution_note: parsed.caution_note || '',
      key_concern: parsed.key_concern || '',
      investor_question: parsed.investor_question || ''
    }
  };
});

return [{
  json: {
    digest: 'Dividend Yield Trap Weekly Digest\n\nNo candidates exceeded the configured risk threshold of 60 during this scan.',
    risk_count: 0,
    generated_at: new Date().toISOString()
  }
}];

return $input.all().map(item => {
  const data = item.json;

  const payoutRatio = Number(data.payout_ratio ?? 0);
  const earningsGrowth = Number(data.earnings_growth ?? 0);
  const revenueGrowth = Number(data.revenue_growth ?? 0);
  const dividendGrowth = Number(data.dividend_growth ?? 0);
  const cuts = Number(data.dividend_cuts_last_5_years ?? 0);

  let sustainabilityScore = 100;

  if (payoutRatio > 0.90) sustainabilityScore -= 35;
  else if (payoutRatio > 0.75) sustainabilityScore -= 20;
  else if (payoutRatio > 0.60) sustainabilityScore -= 10;

  if (earningsGrowth < -0.10) sustainabilityScore -= 25;
  else if (earningsGrowth < 0) sustainabilityScore -= 15;
  else if (earningsGrowth < 0.05) sustainabilityScore -= 5;

  if (revenueGrowth < -0.10) sustainabilityScore -= 15;
  else if (revenueGrowth < 0) sustainabilityScore -= 10;

  if (dividendGrowth < 0) sustainabilityScore -= 10;

  sustainabilityScore -= Math.min(cuts * 10, 30);
  sustainabilityScore = Math.max(0, Math.min(100, sustainabilityScore));

  return {
    json: {
      ...data,
      sustainability_score: sustainabilityScore
    }
  };
});

return $input.all().map(item => {
  const data = item.json;

  const payoutRatio = Number(data.payout_ratio ?? 0);
  const dividendYield = Number(data.dividend_yield ?? 0);
  const earningsGrowth = Number(data.earnings_growth ?? 0);
  const revenueGrowth = Number(data.revenue_growth ?? 0);
  const cuts = Number(data.dividend_cuts_last_5_years ?? 0);
  const sustainability = Number(data.sustainability_score ?? 0);

  let riskScore = 100 - sustainability;

  if (dividendYield >= 0.08) riskScore += 10;
  else if (dividendYield >= 0.06) riskScore += 5;

  if (payoutRatio >= 0.90) riskScore += 15;
  else if (payoutRatio >= 0.75) riskScore += 8;

  if (earningsGrowth < 0) riskScore += 8;
  if (revenueGrowth < 0) riskScore += 5;

  riskScore += Math.min(cuts * 8, 16);
  riskScore = Math.max(0, Math.min(100, Math.round(riskScore)));

  let riskLevel = 'Low';

  if (riskScore >= 75) riskLevel = 'High';
  else if (riskScore >= 60) riskLevel = 'Medium';

  return {
    json: {
      ...data,
      risk_score: riskScore,
      risk_level: riskLevel
    }
  };
});

return $input.all().map(item => {
  const data = item.json;
  const flags = [];

  const payoutRatio = Number(data.payout_ratio ?? 0);
  const earningsGrowth = Number(data.earnings_growth ?? 0);
  const revenueGrowth = Number(data.revenue_growth ?? 0);
  const dividendGrowth = Number(data.dividend_growth ?? 0);
  const cuts = Number(data.dividend_cuts_last_5_years ?? 0);
  const dividendYield = Number(data.dividend_yield ?? 0);

  if (payoutRatio >= 0.90) flags.push('Very high payout ratio');
  else if (payoutRatio >= 0.75) flags.push('Elevated payout ratio');

  if (earningsGrowth < 0) flags.push('Declining earnings');
  if (revenueGrowth < 0) flags.push('Declining revenue');
  if (dividendGrowth < 0) flags.push('Dividend growth is negative');
  if (cuts > 0) flags.push(`Dividend cuts in last 5 years: ${cuts}`);
  if (dividendYield >= 0.08) flags.push('Unusually high dividend yield');

  return {
    json: {
      ...data,
      red_flags: flags,
      red_flag_count: flags.length
    }
  };
});

const aiItems = $input.all();

const riskItems = $('Identify Yield Trap Red Flags').all();

return aiItems.map((item, index) => {
  const ai = item.json;
  const risk = riskItems[index]?.json || {};

  return {
    json: {
      scan_date: new Date().toISOString(),

      symbol: risk.symbol || '',
      company_name: risk.company_name || '',
      sector: risk.sector || '',

      ex_dividend_date: risk.ex_dividend_date || '',
      dividend_per_share: Number(risk.dividend_per_share || 0),
      share_price: Number(risk.share_price || 0),
      dividend_yield: Number(risk.dividend_yield || 0),

      payout_ratio: Number(risk.payout_ratio || 0),
      eps: Number(risk.eps || 0),
      earnings_growth: Number(risk.earnings_growth || 0),
      revenue_growth: Number(risk.revenue_growth || 0),
      dividend_growth: Number(risk.dividend_growth || 0),

      dividend_cuts_last_5_years: Number(
        risk.dividend_cuts_last_5_years || 0
      ),

      sustainability_score: Number(
        risk.sustainability_score || 0
      ),

      risk_score: Number(risk.risk_score || 0),
      risk_level: risk.risk_level || '',

      red_flag_count: Number(
        risk.red_flag_count || 0
      ),

      red_flags: Array.isArray(risk.red_flags)
        ? risk.red_flags.join('; ')
        : String(risk.red_flags || ''),

      caution_note: ai.caution_note || '',
      key_concern: ai.key_concern || '',
      investor_question: ai.investor_question || ''
    }
  };
});

const rows = $input.all().map(item => item.json);

const sorted = rows.sort((a, b) => Number(b.risk_score || 0) - Number(a.risk_score || 0));

let digest = 'Dividend Yield Trap Weekly Digest\n\n';

digest += `High-risk candidates detected: ${sorted.length}\n\n`;

for (const row of sorted) {
  digest += `${row.symbol} - ${row.company_name}\n`;
  digest += `Risk score: ${row.risk_score}/100 (${row.risk_level})\n`;
  digest += `Ex-dividend date: ${row.ex_dividend_date}\n`;
  digest += `Dividend yield: ${(Number(row.dividend_yield || 0) * 100).toFixed(2)}%\n`;
  digest += `Payout ratio: ${(Number(row.payout_ratio || 0) * 100).toFixed(2)}%\n`;
  digest += `Sustainability score: ${row.sustainability_score}/100\n`;
  digest += `Red flags: ${row.red_flags || 'None listed'}\n`;
  digest += `Caution: ${row.caution_note || 'Review the fundamentals before relying on the dividend yield.'}\n\n`;
}

return [{
  json: {
    digest,
    risk_count: sorted.length,
    generated_at: new Date().toISOString()
  }
}];

